import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import API from '../api/axios';
import { Plus } from 'lucide-react';

const MyComplaints = () => {
  const [complaints, setComplaints] = useState([]);

  useEffect(() => {
    API.get('/complaints/my')
      .then(res => setComplaints(res.data))
      .catch(err => console.error(err));
  }, []);

  const getStatusColor = (status) => {
    switch (status) {
      case 'Resolved': return 'bg-emerald-100 text-emerald-800 border-emerald-300';
      case 'In-Progress': return 'bg-amber-100 text-amber-800 border-amber-300';
      default: return 'bg-red-100 text-red-800 border-red-300';
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold text-slate-900">My Maintenance Complaints</h1>
        <Link to="/new-complaint" className="bg-sky-600 hover:bg-sky-700 text-white px-4 py-2 rounded-lg flex items-center space-x-1 font-semibold">
          <Plus className="w-4 h-4" /><span>Raise Complaint</span>
        </Link>
      </div>

      {complaints.length === 0 ? (
        <div className="bg-white p-8 text-center rounded-xl shadow border">No complaints submitted yet.</div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {complaints.map((item) => (
            <div key={item._id} className="bg-white p-6 rounded-xl shadow border flex flex-col justify-between">
              <div>
                <div className="flex justify-between items-start mb-2">
                  <span className="text-xs font-bold text-sky-600 uppercase tracking-wider">{item.category}</span>
                  <span className={`px-2.5 py-0.5 rounded-full text-xs font-bold border ${getStatusColor(item.status)}`}>
                    {item.status}
                  </span>
                </div>
                <h3 className="font-bold text-lg text-slate-900">{item.title}</h3>
                <p className="text-sm text-slate-600 mt-1">{item.description}</p>
                <p className="text-xs text-slate-500 mt-2 font-medium">📍 Location: {item.location}</p>
                {item.assignedTo !== 'Unassigned' && (
                  <p className="text-xs text-slate-500 mt-1">👷 Assigned To: {item.assignedTo}</p>
                )}
              </div>

              {item.image && (
                <div className="mt-4">
                  <img src={`http://localhost:5000${item.image}`} alt="Proof" className="h-32 w-full object-cover rounded-lg border" />
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default MyComplaints;
